window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-39ba87a45d9a8163"]={"versions": [{"id": "FIG-39ba87a45d9a8163", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherschema / Datenstrukturdiagramm im Kontext des AUTOSAR RTE Kalibrierungs- und Parametersystems (Software Architecture / Memory Layout). Es illustriert das Speicherlayout und die Verzeigerung für die Kalibrierungsmethode „single pointered“ (Single Pointered Method Context).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Calibration reference table</strong>: Blau umrandete vertikale Zeigertabelle / Arraystruktur mit einzelnen Einträgen (Slots/Referenzen), die jeweils auf den Beginn einer Parametergruppe verweisen.\n</li><li><strong>CalprmElementGroup</strong>: Gestrichelt umrandete zusammenhängende Speichereinheit bzw. Datenblock, repräsentiert eine logisch gebündelte Kalibrierparametergruppe. Mehrere dieser Gruppen unterschiedlicher Länge existieren im Adressraum und werden von der Referenztabelle aus referenziert.\n</li><li><strong>CalprmElement</strong>: Einzelnes Kalibrierungs- bzw. Parameterelement (Zelle) innerhalb einer <code>CalprmElementGroup</code>.\n</li><li><strong>Referenzbeziehungen</strong>: Blaue gestrichelte Pfeile führen von den Tabelleneinträgen der <code>Calibration reference table</code> auf die jeweiligen Instanzen von <code>CalprmElementGroup</code>. Auslassungspunkte (<code>...</code>) deuten die Fortsetzbarkeit der Tabellen- und Elementstrukturen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Kontrollfluss. Der Datenzugriff zur Laufzeit erfolgt indirekt: Das Laufzeitsystem oder ein Software-Component (SWC) adressiert eine <code>CalprmElementGroup</code> über einen Zeigereintrag in der zentralen <code>Calibration reference table</code> und greift anschließend relativ oder per Element-Offset auf das gewünschte <code>CalprmElement</code> zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die RTE-Implementierung im „single pointered“-Kalibrierungsmodus:</p>\n<ul class=\"fig-list\"><li>Erfordert die Bündelung von <code>CalprmElement</code>-Instanzen in zusammenhängende Gruppen (<code>CalprmElementGroup</code>), um den Overhead der Pointer-Tabelle zu minimieren.\n</li><li>Für jede Gruppe existiert genau eine Basiszeigerreferenz in der <code>Calibration reference table</code>.\n</li><li>Ermöglicht Online-Kalibrierung bzw. das Umschalten ganzer Parametersätze (Page Switching) auf Gruppenebene durch Aktualisierung einzelner Zeiger in der Referenztabelle.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-93963b600d164abb", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherschema / Datenstrukturdiagramm im Kontext des AUTOSAR RTE Kalibrierungs- und Parametersystems (Software Architecture / Memory Layout). Es illustriert das Speicherlayout und die Verzeigerung für die Kalibrierungsmethode „single pointered“ (Single Pointered Method Context).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Calibration reference table</strong>: Blau umrandete vertikale Zeigertabelle / Arraystruktur mit einzelnen Einträgen (Slots/Referenzen), die jeweils auf den Beginn einer Parametergruppe verweisen.\n</li><li><strong>CalprmElementGroup</strong>: Gestrichelt umrandete zusammenhängende Speichereinheit bzw. Datenblock, repräsentiert eine logisch gebündelte Kalibrierparametergruppe. Mehrere dieser Gruppen unterschiedlicher Länge existieren im Adressraum und werden von der Referenztabelle aus referenziert.\n</li><li><strong>CalprmElement</strong>: Einzelnes Kalibrierungs- bzw. Parameterelement (Zelle) innerhalb einer <code>CalprmElementGroup</code>.\n</li><li><strong>Referenzbeziehungen</strong>: Blaue gestrichelte Pfeile führen von den Tabelleneinträgen der <code>Calibration reference table</code> auf die jeweiligen Instanzen von <code>CalprmElementGroup</code>. Auslassungspunkte (<code>...</code>) deuten die Fortsetzbarkeit der Tabellen- und Elementstrukturen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Kontrollfluss. Der Datenzugriff zur Laufzeit erfolgt indirekt: Das Laufzeitsystem oder ein Software-Component (SWC) adressiert eine <code>CalprmElementGroup</code> über einen Zeigereintrag in der zentralen <code>Calibration reference table</code> und greift anschließend relativ oder per Element-Offset auf das gewünschte <code>CalprmElement</code> zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die RTE-Implementierung im „single pointered“-Kalibrierungsmodus:</p>\n<ul class=\"fig-list\"><li>Erfordert die Bündelung von <code>CalprmElement</code>-Instanzen in zusammenhängende Gruppen (<code>CalprmElementGroup</code>), um den Overhead der Pointer-Tabelle zu minimieren.\n</li><li>Für jede Gruppe existiert genau eine Basiszeigerreferenz in der <code>Calibration reference table</code>.\n</li><li>Ermöglicht Online-Kalibrierung bzw. das Umschalten ganzer Parametersätze (Page Switching) auf Gruppenebene durch Aktualisierung einzelner Zeiger in der Referenztabelle.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9aff22bb2f38391e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherschema / Datenstrukturdiagramm im Kontext des AUTOSAR RTE Kalibrierungs- und Parametersystems (Software Architecture / Memory Layout). Es illustriert das Speicherlayout und die Verzeigerung für die Kalibrierungsmethode „single pointered“ (Single Pointered Method Context).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Calibration reference table</strong>: Blau umrandete vertikale Zeigertabelle / Arraystruktur mit einzelnen Einträgen (Slots/Referenzen), die jeweils auf den Beginn einer Parametergruppe verweisen.\n</li><li><strong>CalprmElementGroup</strong>: Gestrichelt umrandete zusammenhängende Speichereinheit bzw. Datenblock, repräsentiert eine logisch gebündelte Kalibrierparametergruppe. Mehrere dieser Gruppen unterschiedlicher Länge existieren im Adressraum und werden von der Referenztabelle aus referenziert.\n</li><li><strong>CalprmElement</strong>: Einzelnes Kalibrierungs- bzw. Parameterelement (Zelle) innerhalb einer <code>CalprmElementGroup</code>.\n</li><li><strong>Referenzbeziehungen</strong>: Blaue gestrichelte Pfeile führen von den Tabelleneinträgen der <code>Calibration reference table</code> auf die jeweiligen Instanzen von <code>CalprmElementGroup</code>. Auslassungspunkte (<code>...</code>) deuten die Fortsetzbarkeit der Tabellen- und Elementstrukturen an.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamischen Kontrollfluss. Der Datenzugriff zur Laufzeit erfolgt indirekt: Das Laufzeitsystem oder ein Software-Component (SWC) adressiert eine <code>CalprmElementGroup</code> über einen Zeigereintrag in der zentralen <code>Calibration reference table</code> und greift anschließend relativ oder per Element-Offset auf das gewünschte <code>CalprmElement</code> zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für die RTE-Implementierung im „single pointered“-Kalibrierungsmodus:</p>\n<ul class=\"fig-list\"><li>Erfordert die Bündelung von <code>CalprmElement</code>-Instanzen in zusammenhängende Gruppen (<code>CalprmElementGroup</code>), um den Overhead der Pointer-Tabelle zu minimieren.\n</li><li>Für jede Gruppe existiert genau eine Basiszeigerreferenz in der <code>Calibration reference table</code>.\n</li><li>Ermöglicht Online-Kalibrierung bzw. das Umschalten ganzer Parametersätze (Page Switching) auf Gruppenebene durch Aktualisierung einzelner Zeiger in der Referenztabelle.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-39ba87a45d9a8163", "to": "FIG-93963b600d164abb", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-93963b600d164abb", "to": "FIG-9aff22bb2f38391e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
